import { test } from 'node:test';
import assert from 'node:assert/strict';
import { routes, dispatch } from '../src/app.js';

// Every route, with stores that fail with an internal detail: the response must not carry the detail.
const DETAIL = 'SQLITE_CORRUPT at /var/data/rooms.db';
const fail = () => { throw new Error(DETAIL); };
const store = new Proxy({}, { get: (_, k) => (k === 'then' ? undefined : fail) });
const deps = new Proxy({}, { get: (_, k) => (k === 'then' ? undefined : store) });
const req = { params: { id: 'r1' }, body: { roomId: 'r1', date: '2026-12-01', name: 'Oak' }, query: { date: '2026-12-01' }, user: { id: 'u1' } };

for (const name of Object.keys(routes)) {
  test(`${name}: a failing store does not leak into the response`, async () => {
    const r = await dispatch(name, req, deps);
    assert.ok(!JSON.stringify(r).includes('SQLITE_CORRUPT'), JSON.stringify(r));
  });
}
